{
  "tasks": [
    {
      "task_id": "T1",
      "title": "项目任务整体概况与工时分布",
      "business_question": "统计总任务数、涉及的项目数量，以及工时的平均值和总和，以了解数据基本规模和投入情况。",
      "priority": "P0",
      "priority_reason": "这是探索性分析的基础，提供数据集的整体画像（规模、覆盖范围、核心数值指标），是回答“主要分布”问题的必要前提。删除后无法建立对数据的初步认知。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1_1",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_task_count"
              },
              {
                "function": "distinct_count",
                "field": "field_0002",
                "alias": "unique_project_count"
              },
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_work_hours"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_work_hours"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T2",
      "title": "各项目的任务分布与工时差异",
      "business_question": "按项目分组，统计每个项目的任务数量和工时总和/均值，识别哪些项目任务更多或耗时更长。",
      "priority": "P0",
      "priority_reason": "直接回应“主要分布与差异”的核心需求，通过项目维度揭示资源分配的不均衡性或集中度。这是探索业务结构的关键视角。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S2_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "tasks_per_project"
              },
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "hours_per_project_sum"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "hours_per_project_avg"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S2_2",
          "operation": "sort",
          "params": {
            "field": "tasks_per_project",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T3",
      "title": "不同状态下的任务数量与工时特征",
      "business_question": "按状态分组，统计各状态的任务数量及平均工时，分析未完成/已完成等状态在数量和工作量上的差异。",
      "priority": "P1",
      "priority_reason": "补充性分析，从生命周期角度观察数据分布。虽然不如项目维度核心，但能揭示工作流瓶颈或负载分布，有助于全面理解“差异”。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S3_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "tasks_per_status"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_hours_per_status"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        }
      ]
    }
  ]
}
